params.command:
$ErrorActionPreference='Continue'
$repo='C:\Users\Xxkan\local-ai-workspaces\mhw-mods'
$services=@(Get-Service -ErrorAction SilentlyContinue | Where-Object { $_.Name -like 'actions.runner*' -or $_.DisplayName -like '*GitHub Actions Runner*' } | Select-Object Name,DisplayName,Status,StartType)
$procs=@(Get-Process -ErrorAction SilentlyContinue | Where-Object { $_.ProcessName -match 'Runner\.(Listener|Worker)|run\.cmd' } | Select-Object Id,ProcessName,Path)
$runnerDirs=@('C:\actions-runner','C:\Users\Xxkan\actions-runner','C:\Users\Xxkan\github-actions-runner') | ForEach-Object { [pscustomobject]@{path=$_;exists=(Test-Path $_)} }
$runnerApi=$null
try { $runnerApi = gh api repos/fengie/mhw-mods/actions/runners --jq '{total_count:.total_count,runners:[.runners[]|{id,name,os,status,busy,labels:[.labels[].name]}]}' 2>$null } catch { $runnerApi = "gh-api-error: $($_.Exception.Message)" }
$agentStatus=$null
try { $agentStatus=(Invoke-RestMethod 'http://127.0.0.1:7331/api/status' -TimeoutSec 5 | ConvertTo-Json -Depth 8 -Compress) } catch { $agentStatus="agentctl-api-error: $($_.Exception.Message)" }
$git=@{}
if(Test-Path $repo){ Push-Location $repo; try { $git=@{branch=(git branch --show-current); head=(git rev-parse HEAD); status=(git status --short); originMain=(git rev-parse origin/main)} } finally { Pop-Location } }
[pscustomobject]@{services=$services;processes=$procs;runnerDirs=$runnerDirs;runnerApi=$runnerApi;agentStatus=$agentStatus;git=$git} | ConvertTo-Json -Depth 10 -Compress
